import Foundation

/// Generation sources shown in the energy mix, grouped from EIA-930 fuel codes.
public enum FuelGroup: String, Sendable, Hashable, Codable, CaseIterable {
    case nuclear, wind, hydro, solar, otherClean, gas, coal, other

    /// Fossil-free groups, as in `EIAFuelMixClient.cleanFuels`.
    public var isClean: Bool {
        switch self {
        case .nuclear, .wind, .hydro, .solar, .otherClean: true
        case .gas, .coal, .other: false
        }
    }

    /// EIA-930 fuel code to group. Battery storage (BAT) returns nil: stored energy was generated by something else.
    public init?(eiaFuel code: String) {
        switch code {
        case "NUC": self = .nuclear
        case "WND": self = .wind
        case "WAT": self = .hydro
        case "SUN", "SNB": self = .solar
        case "GEO": self = .otherClean
        case "NG": self = .gas
        case "COL": self = .coal
        case "BAT": return nil
        default: self = .other
        }
    }
}

/// Hourly generation by group for one balancing authority, in MWh.
public typealias FuelHistory = [Date: [FuelGroup: Double]]

/// Share of each generation group, summing to 1.
public struct EnergyMix: Sendable, Hashable, Codable {
    public enum Basis: String, Sendable, Hashable, Codable {
        /// Hours inside the requested period.
        case period
        /// The period has no published hours yet (or is older than the data kept), so the whole history is used.
        case recentAverage
    }

    public var shares: [FuelGroup: Double]
    public var basis: Basis
    /// Published hours the mix is based on, summed over balancing authorities.
    public var hours: Int

    public init(shares: [FuelGroup: Double], basis: Basis, hours: Int) {
        self.shares = shares
        self.basis = basis
        self.hours = hours
    }

    public var cleanShare: Double { shares.filter { $0.key.isClean }.values.reduce(0, +) }

    /// Mix of one balancing authority over `interval`, or over its whole history when no hour falls inside.
    public static func from(_ history: FuelHistory, interval: DateInterval) -> EnergyMix? {
        let inside = history.filter { interval.start <= $0.key && $0.key < interval.end }
        let (hours, basis) = inside.isEmpty ? (history, Basis.recentAverage) : (inside, Basis.period)
        var totals: [FuelGroup: Double] = [:]
        for groups in hours.values {
            for (group, mwh) in groups { totals[group, default: 0] += mwh }
        }
        let sum = totals.values.reduce(0, +)
        guard sum > 0 else { return nil }
        return EnergyMix(shares: totals.mapValues { $0 / sum }, basis: basis, hours: hours.count)
    }

    /// Weighted average of several mixes. Weights are renormalized over the mixes present.
    /// The basis is `recentAverage` if any part used it.
    public static func weighted(_ parts: [(mix: EnergyMix, weight: Double)]) -> EnergyMix? {
        let total = parts.reduce(0) { $0 + $1.weight }
        guard total > 0 else { return nil }
        var shares: [FuelGroup: Double] = [:]
        for part in parts {
            for (group, share) in part.mix.shares { shares[group, default: 0] += share * part.weight / total }
        }
        let basis: Basis = parts.contains { $0.mix.basis == .recentAverage } ? .recentAverage : .period
        return EnergyMix(shares: shares, basis: basis, hours: parts.reduce(0) { $0 + $1.mix.hours })
    }
}

/// Estimated generation behind the energy of a report: each tool's energy split by its provider's mix.
public struct ReportEnergyMix: Sendable, Hashable, Codable {
    /// Mid energy (Wh) per generation group.
    public var whByGroup: [FuelGroup: Double]
    public var basis: EnergyMix.Basis

    public var totalWh: Double { whByGroup.values.reduce(0, +) }
    public var cleanShare: Double {
        let total = totalWh
        return total > 0 ? whByGroup.filter { $0.key.isClean }.values.reduce(0, +) / total : 0
    }

    public func share(_ group: FuelGroup) -> Double {
        let total = totalWh
        return total > 0 ? (whByGroup[group] ?? 0) / total : 0
    }

    /// Splits each source's energy by the mix of the provider behind it. Sources without a mix are left out.
    public static func combine(energyBySource: [UsageSource: Double], mixes: [GridProvider: EnergyMix]) -> ReportEnergyMix? {
        var whByGroup: [FuelGroup: Double] = [:]
        var usedFallback = false
        for (source, wh) in energyBySource where wh > 0 {
            guard let mix = mixes[GridProvider(source: source)] else { continue }
            usedFallback = usedFallback || mix.basis == .recentAverage
            for (group, share) in mix.shares { whByGroup[group, default: 0] += wh * share }
        }
        guard whByGroup.values.reduce(0, +) > 0 else { return nil }
        return ReportEnergyMix(whByGroup: whByGroup, basis: usedFallback ? .recentAverage : .period)
    }
}
